{
  "qid": "0009_gd_liondance_l3_01",
  "sample_id": "0009",
  "gen_prompt": "请创作一幅高细节、写实纪实风格的传统民俗表演画面：一场广东醒狮表演正在进行，画面定格在主体腾空掠过红色地毯的瞬间。采用正面略低机位的中景构图，完整呈现主体及其下方区域。背景设为佛山古建筑庭院，晨雾笼罩，檐下悬挂节庆旗幡，地面有柔和的斜向日光与清晰投影，整体气氛热烈而庄重。",
  "invocation": "L3",
  "knowledge_dim": "传统民俗表演艺术的器物形制、角色体系与表演结构推理",
  "fidelity_checks": [
    {
      "check": "在“广东醒狮表演正在进行、主体腾空”的前提下，由醒狮的传统定义推导出画面主体应为装饰化、夸张彩绘的南狮道具，而非自然动物形态或北方狮具的简化头型。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[1]"],
        "derivation_chain": "广东醒狮表演正在进行且主体腾空→广东醒狮属于融合民俗工艺与表演的南狮体系→主体呈现为装饰化、夸张彩绘的南狮道具，而非写实生物狮子或北狮无角写实头型"
      },
      "rubric": {
        "tier_0": "主体缺失，或主体明显是写实生物学狮子、北狮无角写实头型，或完全无法辨认为南狮道具。",
        "tier_1": "主体大致可辨认为南狮道具，但装饰化和彩绘特征较弱，或局部呈现出明显的自然狮子形态、北狮化简化头型。",
        "tier_2": "主体清楚呈现为装饰化、夸张彩绘的南狮道具，造型与传统醒狮狮头相符，不被写实生物狮子或北狮无角写实头型替代。"
      },
      "variants_used": "无变体，覆盖[1]全部要求",
      "visibility_requirement": "主体正面或三分之二正面至少占画面中部并清晰可辨；若因腾跃姿态发生轻微透视变形，只要整体形制仍可判定为南狮道具即可。",
      "weight": 1.0
    },
    {
      "check": "由南狮传统造型知识推导出，主体额前应出现标志性的独角状突起。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[2]"],
        "derivation_chain": "广东醒狮表演正在进行→南狮具有标志性额前造型→主体额前出现清晰可辨的独角状突起"
      },
      "rubric": {
        "tier_0": "额前完全没有突起，或突起明显不是独角状结构。",
        "tier_1": "额前有疑似突起，但被遮挡、模糊或形状不完整，难以稳定判断为独角状造型。",
        "tier_2": "主体额前清楚可见一个独角状突起；因视角造成的轻微侧偏、透视缩短或装饰包覆不影响其独角状特征判断。"
      },
      "variants_used": "无变体，覆盖[2]全部要求",
      "visibility_requirement": "额头区域需至少有正面或三分之二正面可见；若该处被完全遮挡，本条按不可判定处理，不因不可见直接判错。",
      "weight": 1.0
    },
    {
      "check": "由南狮狮头的传统面部结构推导出，主体应具有大而圆的凸眼以及宽大的可开合式嘴部造型。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[3]"],
        "derivation_chain": "广东醒狮表演正在进行→南狮狮头采用夸张的面部器物结构→主体呈现大而圆的凸眼与宽大的可开合式嘴部"
      },
      "rubric": {
        "tier_0": "眼部和嘴部均不具备醒狮特征，或主体呈现普通动物狮子的眼口结构。",
        "tier_1": "眼部或嘴部仅有一项较明显符合，另一项比例、凸出程度或开合结构不清楚。",
        "tier_2": "双眼均明显大而圆并具有凸出感，嘴部宽大且能看出可开合的道具结构；不同合法装饰配色不影响本条得分。"
      },
      "variants_used": "无变体，覆盖[3]全部要求",
      "visibility_requirement": "面部正面至少有约三分之二可见，双眼与嘴部不能同时被完全遮挡；若嘴部处于闭合状态，只要宽大可开合结构清晰可判即可。",
      "weight": 1.0
    },
    {
      "check": "由“主体腾空掠过红色地毯”的表演前提和醒狮的双人或多人操演常识推导出，狮被下方应能看到实际操演者的腿脚或身体部分，而不是无人摆放的物件。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[4]"],
        "derivation_chain": "主体腾空掠过红色地毯→醒狮腾跃需要操演者在狮被内部配合完成→狮被下方出现可见的操演者腿脚或身体部分，且画面不是无人的静态摆设"
      },
      "rubric": {
        "tier_0": "主体像无人摆设，狮被下方完全没有操演者可见部分，或姿态明显静止站立而非表演状态。",
        "tier_1": "能看出主体处于动作中，但操演者仅露出极少且模糊的局部，或腾跃状态表现不充分。",
        "tier_2": "主体明确处于腾跃表演状态，狮被下方清楚可见操演者的腿脚或身体部分，整体不存在无人静态摆设的矛盾。"
      },
      "variants_used": "无变体，覆盖[4]全部要求",
      "visibility_requirement": "题面已要求完整呈现主体下方区域，因此下方区域应可见；若因运动遮挡仅露出腿脚或身体局部，仍可按满分判断。",
      "weight": 1.0
    },
    {
      "check": "由醒狮表演的服装与道具材质常识推导出，狮身躯干应表现为彩色布制狮被，并可带有流苏或绒毛镶边，而不是动物皮毛或实心雕塑。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[5]"],
        "derivation_chain": "广东醒狮表演正在进行→表演主体由可供操演者穿戴和摆动的狮被构成→狮身躯干呈现彩色布制织物，并可见流苏或绒毛镶边，而非动物皮毛或实心雕塑"
      },
      "rubric": {
        "tier_0": "躯干完全呈现为动物皮毛、裸露生物身体或实心雕塑，无法看出布制狮被。",
        "tier_1": "局部可见织物或装饰边缘，但主体躯干材质混杂，仍有明显动物皮毛或雕塑质感。",
        "tier_2": "躯干整体清楚表现为彩色布制狮被，具有可摆动的织物褶皱、边缘流苏或绒毛装饰，不被动物皮毛或实心雕塑替代。"
      },
      "variants_used": "覆盖“常带流苏或绒毛镶边”这一合法变体；镶边可有可无，核心为彩色布制织物",
      "visibility_requirement": "躯干或狮被下摆至少有一处无遮挡的中近景可见；若部分躯干被操演者遮挡，只依据可见部分判断整体材质。",
      "weight": 1.0
    },
    {
      "check": "由广东醒狮的传统角色体系推导出，狮头主色应属于传统角色脸谱配色体系，而不是任意脱离传统体系的主色设定。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[6]"],
        "derivation_chain": "广东醒狮表演正在进行→醒狮狮头按传统角色形成稳定的脸谱配色体系→狮头主色属于刘备狮黄色、关公狮红色、张飞狮黑色或其他传统南狮配色"
      },
      "rubric": {
        "tier_0": "狮头主色明显属于任意非传统的配色，或主体无可辨识的主色体系。",
        "tier_1": "主色大体接近传统体系，但被大面积非传统颜色覆盖，或颜色关系过于混乱而难以归入传统角色配色。",
        "tier_2": "狮头主色清楚属于传统南狮角色配色：可为刘备狮黄色、关公狮红色、张飞狮黑色，或其他有传统依据的南狮配色；不同合法配色均得满分。"
      },
      "variants_used": "覆盖刘备狮黄色、关公狮红色、张飞狮黑色及其他传统南狮配色全部变体",
      "visibility_requirement": "狮头正面或三分之二正面需有足够面积显示主色；局部阴影、纹样和高光不影响对整体主色的判断。",
      "weight": 1.0
    },
    {
      "check": "由醒狮作为民俗道具而非真实动物的概念边界推导出，画面中不得出现真实生物学形态的狮子充当或替代醒狮主体。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["[7]"],
        "derivation_chain": "广东醒狮表演正在进行→主体是民俗表演道具而非野生动物→画面中不得出现真实生物学形态的狮子充当或替代醒狮"
      },
      "rubric": {
        "tier_0": "出现一只真实生物学形态的狮子充当或替代醒狮主体，或真实狮子成为主要视觉主体。",
        "tier_1": "未出现完整真实狮子，但局部明显出现真实狮子的头、四肢或身体，并造成主体身份混淆。",
        "tier_2": "画面中没有真实生物学形态的狮子充当或替代醒狮，所有主要狮形元素均属于民俗表演道具。"
      },
      "variants_used": "无变体，覆盖[7]全部要求",
      "visibility_requirement": "以整幅画面中可见的主体及背景为判断范围；背景中若出现与主体无关、极小且无法辨认的动物纹样，不按真实狮子实体计入。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "画面中央的广东醒狮表演主体应占据主要视觉面积并成为唯一核心焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "主体缺失、被背景压过，或视觉焦点明显转移到旗幡、建筑等其他元素。",
        "tier_1": "主体存在且较显眼，但尺寸偏小、位置偏边或受到背景干扰，主导性不足。",
        "tier_2": "广东醒狮主体位于画面核心，体量突出、清晰醒目，背景元素起衬托作用。"
      }
    },
    {
      "check": "主体应被描绘为腾空掠过红色地毯的瞬间，而不是静止站立或普通行走。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "主体静止摆放、躺倒，或完全没有腾空掠过的动作迹象。",
        "tier_1": "有运动姿态或离地暗示，但腾空和掠过地毯的瞬间表现不清楚。",
        "tier_2": "主体明确处于腾空动态，四肢、下摆或运动姿态清楚传达掠过红色地毯的瞬间。"
      }
    },
    {
      "check": "画面应采用正面略低机位的中景，并完整呈现主体及其下方区域。",
      "facet": "spatial_3d",
      "rubric": {
        "tier_0": "明显采用背面、俯拍或极端远景，主体下方区域完全缺失。",
        "tier_1": "大致为正面中景，但机位、景别或下方区域呈现不完整。",
        "tier_2": "整体为正面略低机位中景，主体比例合适，主体下方区域清楚可见；轻微透视偏差不影响整体判断。"
      }
    },
    {
      "check": "场景应为晨雾中的佛山古建筑庭院，檐下有节庆旗幡，地面出现斜向日光与投影。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "场景变成完全不同的地点，如现代室内、城市街道或纯抽象背景，且无题面指定环境。",
        "tier_1": "具有中式建筑或节庆现场的部分特征，但佛山古建筑庭院、晨雾或旗幡等环境要素缺失较多。",
        "tier_2": "清楚呈现佛山古建筑庭院、晨雾、檐下节庆旗幡，并能看到符合设定的斜向日光与地面投影。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "lighting_atmosphere",
    "anatomical_fidelity",
    "color_harmony"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "[1]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[2]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[3]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[4]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[5]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[6]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[7]",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "已避免指定狮头具体颜色、面部结构、材质和道具细节；主体采用正面略低机位并要求呈现下方区域，以保证相关推导结论具有最低可见条件。"
}
